const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Geometry for Death Valley National Park from the World Database on Protected Areas.
    const aoi = ee.FeatureCollection("WCMC/WDPA/current/polygons")
        .filter(ee.Filter.eq('WDPA_PID', '555546271'))
        .geometry();

    const date1_start = '2022-07-11';
    const date1_end = '2022-07-12';
    const date2_start = '2022-08-07';
    const date2_end = '2022-08-08';

    // 2. Data Acquisition & Processing Function
    const getWaterExtent = function(startDate, endDate, geometry) {
        // Use Sentinel-2 Surface Reflectance
        let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterDate(startDate, endDate)
            .filterBounds(geometry);

        const imageCount = collection.size().getInfo();
        if (imageCount === 0) {
            return {
                'count': imageCount,
                'water_area': null,
                'cloud_percentage': null
            };
        }

        let image = collection.median().clip(geometry);

        // Cloud masking using the Scene Classification Layer (SCL)
        // Values 4 (vegetation), 5 (not vegetated), 6 (water), 7 (unclassified) are kept.
        const scl = image.select('SCL');
        const mask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(7));
        image = image.updateMask(mask);

        // Calculate cloud percentage for reporting
        const totalPixels = ee.Image.constant(1).reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: 100, // Coarse scale for total area
            maxPixels: 1e9
        }).get('constant');

        const cloudPixels = collection.median().clip(geometry).select('SCL').neq(4).and(scl.neq(5)).and(scl.neq(6)).and(scl.neq(7))
            .reduceRegion({
                reducer: ee.Reducer.sum(),
                geometry: geometry,
                scale: 100,
                maxPixels: 1e9
            }).get('SCL');

        const cloudPercentage = ee.Number(cloudPixels).divide(totalPixels).multiply(100);

        // Calculate Normalized Difference Water Index (NDWI)
        // NDWI = (Green - NIR) / (Green + NIR) -> (B3 - B8) / (B3 + B8)
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');

        // Identify water pixels using a threshold.
        const water = ndwi.gt(0.1);

        // Count the number of water pixels
        const waterArea = water.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: geometry,
            scale: 30, // Use a reasonable scale for the analysis
            maxPixels: 1e12
        }).get('NDWI'); // in square meters

        return {
            'count': imageCount,
            'water_area': ee.Number(waterArea).divide(1e6), // Convert to sq km
            'cloud_percentage': cloudPercentage
        };
    };

    // 3. Calculation for both dates
    const results1_obj = getWaterExtent(date1_start, date1_end, aoi);
    const results2_obj = getWaterExtent(date2_start, date2_end, aoi);

    // 4. Validation & Final Answer
    const imgCount1 = results1_obj.count;
    const imgCount2 = results2_obj.count;

    if (imgCount1 === 0 || imgCount2 === 0) {
        console.log(`Image Count (July 11, 2022): ${imgCount1}`);
        console.log(`Image Count (Aug 7, 2022): ${imgCount2}`);
        console.log('C1: Empty Collection');
        return;
    }

    const water_area1 = results1_obj.water_area.getInfo();
    const cloud_pct1 = results1_obj.cloud_percentage.getInfo();
    const water_area2 = results2_obj.water_area.getInfo();
    const cloud_pct2 = results2_obj.cloud_percentage.getInfo();

    if (water_area1 === null || water_area2 === null) {
        console.log('C2: No Valid Pixels after cloud masking.');
        return;
    }

    console.log(`July 11, 2022 Surface Water (km^2): ${water_area1.toFixed(2)}`);
    console.log(`July 11, 2022 Cloud Cover (%): ${cloud_pct1.toFixed(2)}`);
    console.log(`Aug 7, 2022 Surface Water (km^2): ${water_area2.toFixed(2)}`);
    console.log(`Aug 7, 2022 Cloud Cover (%): ${cloud_pct2.toFixed(2)}`);

    if (water_area2 > water_area1) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred: ', err);
    console.log('D');
});
